package com.nexoskill.evaluation.questionbank.infrastructure.persistence;
import com.nexoskill.evaluation.questionbank.application.model.*; import com.nexoskill.evaluation.questionbank.application.port.out.QuestionCollectionPort; import com.nexoskill.evaluation.questionbank.domain.model.*; import com.nexoskill.evaluation.shared.domain.*; import java.text.Normalizer; import java.time.Clock; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Component;
@Component public class OracleQuestionCollectionAdapter implements QuestionCollectionPort {
 private final SpringDataQuestionCollectionRepository collections;private final SpringDataQuestionCategoryRepository categories;private final SpringDataQuestionRepository questions;private final Clock clock;
 public OracleQuestionCollectionAdapter(SpringDataQuestionCollectionRepository c,SpringDataQuestionCategoryRepository cats,SpringDataQuestionRepository q,Clock clock){collections=c;categories=cats;questions=q;this.clock=clock;}
 public CollectionDetail create(CollectionCommands.Create c){String name=name(c.name()),norm=normalize(name);if(collections.existsByNormalizedName(norm))throw error("COLLECTION_ALREADY_EXISTS","Ya existe una colección con ese nombre.");var cats=resolveCategories(c.categoryPublicIds(),Set.of());var qs=resolveQuestions(c.questionPublicIds());var e=QuestionCollectionJpaEntity.create(UUID.randomUUID().toString(),name,norm,nullable(c.description()),cats,qs,c.actorUserId(),clock.instant());return detail(collections.saveAndFlush(e));}
 public CollectionDetail update(CollectionCommands.Update c){String id=PublicIdNormalizer.requiredUuid(c.publicId(),"COLLECTION_ID_INVALID","La colección indicada no es válida.");var e=collections.findForUpdate(id).orElseThrow(()->error("COLLECTION_NOT_FOUND","La colección solicitada no existe."));if(e.getVersion()!=c.expectedEntityVersion())throw error("COLLECTION_CONCURRENT_MODIFICATION","La colección fue modificada por otra persona.");String name=name(c.name()),norm=normalize(name);if(collections.existsByNormalizedNameAndPublicIdNot(norm,id))throw error("COLLECTION_ALREADY_EXISTS","Ya existe una colección con ese nombre.");Set<String> existing=e.getCategories().stream().map(QuestionCategoryJpaEntity::getPublicId).collect(java.util.stream.Collectors.toSet());e.apply(name,norm,nullable(c.description()),resolveCategories(c.categoryPublicIds(),existing),resolveQuestions(c.questionPublicIds()),c.actorUserId(),clock.instant());return detail(collections.saveAndFlush(e));}
 public CollectionDetail get(String id){String p=PublicIdNormalizer.requiredUuid(id,"COLLECTION_ID_INVALID","La colección indicada no es válida.");return detail(collections.findByPublicId(p).orElseThrow(()->error("COLLECTION_NOT_FOUND","La colección solicitada no existe.")));}
 public CollectionPage search(String query,String status,int page,int size){String q=query==null||query.isBlank()?null:query.trim().toLowerCase(Locale.ROOT);String s=status==null||status.isBlank()?null:status.trim().toUpperCase(Locale.ROOT);Page<QuestionCollectionJpaEntity> p=collections.search(q,s,PageRequest.of(page,size));return new CollectionPage(p.getContent().stream().map(this::summary).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
 public CollectionDetail changeStatus(CollectionCommands.ChangeStatus c){String p=PublicIdNormalizer.requiredUuid(c.publicId(),"COLLECTION_ID_INVALID","La colección indicada no es válida.");var e=collections.findForUpdate(p).orElseThrow(()->error("COLLECTION_NOT_FOUND","La colección solicitada no existe."));if(e.getVersion()!=c.expectedEntityVersion())throw error("COLLECTION_CONCURRENT_MODIFICATION","La colección fue modificada por otra persona. Recarga la información.");e.changeStatus(c.status(),c.actorUserId(),clock.instant());return detail(collections.saveAndFlush(e));}
 private Set<QuestionCategoryJpaEntity> resolveCategories(List<String> ids,Set<String> existing){Set<String> canonical=ids.stream().map(v->PublicIdNormalizer.requiredUuid(v,"CATEGORY_ID_INVALID","Una categoría no es válida.")).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));var found=categories.findAllByPublicIdIn(canonical);if(found.size()!=canonical.size())throw error("CATEGORY_NOT_FOUND","Una categoría seleccionada no existe.");for(var e:found)if(e.getStatus()!=CatalogStatus.ACTIVE&&!existing.contains(e.getPublicId()))throw error("CATEGORY_INACTIVE","La categoría "+e.getName()+" está inactiva.");return new LinkedHashSet<>(found);}
 private Set<QuestionJpaEntity> resolveQuestions(List<String> ids){Set<String> canonical=ids.stream().map(v->PublicIdNormalizer.requiredUuid(v,"QUESTION_ID_INVALID","Una pregunta no es válida.")).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));var found=questions.findAllByPublicIdIn(canonical);if(found.size()!=canonical.size())throw error("QUESTION_NOT_FOUND","Una pregunta seleccionada no existe.");for(var q:found)if(q.getStatus()!=QuestionStatus.ACTIVE)throw error("QUESTION_ARCHIVED","No se pueden agregar preguntas archivadas.");return new LinkedHashSet<>(found);}
 private List<QuestionJpaEntity> effective(QuestionCollectionJpaEntity e){LinkedHashMap<Long,QuestionJpaEntity> map=new LinkedHashMap<>();for(var q:e.getQuestions())if(q.getStatus()==QuestionStatus.ACTIVE)map.put(q.getId(),q);Set<Long> catIds=e.getCategories().stream().map(QuestionCategoryJpaEntity::getId).collect(java.util.stream.Collectors.toSet());if(!catIds.isEmpty())for(var q:questions.findByStatusAndAnyCategoryIdIn(QuestionStatus.ACTIVE.name(),catIds))map.put(q.getId(),q);return map.values().stream().sorted(java.util.Comparator.comparing(QuestionJpaEntity::getStatement,String.CASE_INSENSITIVE_ORDER)).toList();}
 private CollectionSummary summary(QuestionCollectionJpaEntity e){return new CollectionSummary(e.getPublicId(),e.getName(),e.getDescription(),e.getStatus(),e.getCategories().size(),e.getQuestions().size(),effective(e).size(),e.getVersion(),e.getCreatedAt(),e.getUpdatedAt());}
 private CollectionDetail detail(QuestionCollectionJpaEntity e){return new CollectionDetail(e.getPublicId(),e.getName(),e.getDescription(),e.getStatus(),e.getCategories().stream().map(c->new QuestionCategoryRef(c.getPublicId(),c.getCode(),c.getName(),c.getStatus())).sorted(java.util.Comparator.comparing(QuestionCategoryRef::name)).toList(),e.getQuestions().stream().map(this::questionSummary).toList(),effective(e).stream().map(this::questionSummary).toList(),e.getVersion(),e.getCreatedAt(),e.getUpdatedAt());}
 private QuestionSummary questionSummary(QuestionJpaEntity q){return new QuestionSummary(q.getPublicId(),q.getStatement(),q.getType().getCode(),q.getType().getName(),q.getDifficulty().getCode(),q.getDifficulty().getName(),q.getCategories().stream().map(c->new QuestionCategoryRef(c.getPublicId(),c.getCode(),c.getName(),c.getStatus())).toList(),q.getStatus(),q.getPromptMedia()!=null||q.getOptions().stream().anyMatch(o->o.getMedia()!=null),q.getCreatedAt(),q.getUpdatedAt());}
 private String name(String v){if(v==null||v.isBlank())throw error("COLLECTION_NAME_REQUIRED","El nombre es obligatorio.");return v.trim().replaceAll("\\s+"," ");}private String normalize(String v){return Normalizer.normalize(v,Normalizer.Form.NFKC).replaceAll("\\s+"," ").trim().toLowerCase(Locale.ROOT);}private String nullable(String v){return v==null||v.isBlank()?null:v.trim();}private BusinessException error(String c,String m){return new BusinessException(c,m);}
}
